/*
 * BRING A POINTED-AT ROW INTO VIEW (TASK-L165 §4), and only when it can be seen.
 *
 * A jump changes three things at once — which surface is mounted, which row is
 * open, and where the page is — and the first two land over the next frames.
 * Scrolling in the same tick as the change that opens the row centres the
 * row's COLLAPSED height and the expansion arrives underneath it: L142 measured
 * a panel opening 31 pixels below the fold that way. So this waits on the
 * CONDITION — the row exists and carries what open looks like — rather than on
 * a guessed delay, which is right until the first slow render.
 *
 * `block: 'start'`: the reader asked to see THIS entry, top first.
 */
const selector = String(Inputs.selector || '');
const openSelector = String(Inputs.openSelector || '');
if (!selector || typeof window === 'undefined') return;
let frames = 0;
const look = () => {
  const el = document.querySelector(selector);
  const open = el && (!openSelector || el.querySelector(openSelector));
  if (open) {
    el.scrollIntoView({ block: 'start' });
    return;
  }
  /* Two seconds of frames, then stop: a row that never arrives is a row the
     page does not have, and scrolling somewhere else would be worse. */
  if (++frames < 120) window.requestAnimationFrame(look);
};
window.requestAnimationFrame(look);
